                update_req = None;
                batch_perms = None;
            }
        });
        if num_ops == 1 {
            let tracked batch_token_value = batch_perms.tracked_unwrap();
            let op = DT::clone_write_op(
                &self.contexts[thread_idx].batch.0.borrow(Tracked(&batch_token_value)).op,
